import json,csv
with open('json/zip_code.json') as f: zdata=json.load(f)
zip2state={str(r['zip_code']).zfill(5): r['state'] for r in zdata['records']}
ilzips={z for z,s in zip2state.items() if s=='Illinois'}
print('IL zip sample:',sorted(ilzips)[:5])
with open('csv/member.csv') as f: members=list(csv.DictReader(f))
with_zeros={m['zip'].zfill(5): m for m in members}
for z in list(zip2state.keys())[:10]:
    m=with_zeros.get(z)
    if m and zip2state[z]=='Illinois':
        print('Match:',m)
print('Total IL matches:',sum(1 for m in members if m['zip'].zfill(5) in ilzips))

